from collections import defaultdict

def group_and_sort(records):
    groups = defaultdict(list)

    for r in records:
        item = dict(r)
        item["score"] = item.get("score", 0)
        groups[item["category"]].append(item)

    return {
        category: sorted(items, key=lambda x: x["score"])
        for category, items in groups.items()
    }


# Example
data = [
    {"id": 1, "category": "fruit", "name": "apple", "score": 7},
    {"id": 2, "category": "fruit", "name": "banana"},  # missing score -> 0
    {"id": 3, "category": "veg", "name": "carrot", "score": 5},
    {"id": 4, "category": "fruit", "name": "pear", "score": 3},
    {"id": 5, "category": "veg", "name": "pea", "score": 2},
]

result = group_and_sort(data)
print(result)
